Fix a group $G$ acting
on the right on a set $X$; fix a set $S$ generating $G$ as a monoid;
and fix a basepoint $x_0\in X$.

Consider now $n>M$. We then have $\ell,m<n$. By induction, we have
  $\Delta(\ell)\le\Delta^*(\ell)$ and $\Delta(m)\le\Delta^*(m)$; so,
  using concavity of $\Delta^*$,
  \begin{align*}
    \Delta(n) &\le\Delta^*(\ell)+\Delta^*(m)\le 2\Delta^*\Big(\frac12(\ell+m)\Big)\le2\Delta^*\Big(\frac\eta2\big(n+\tfrac C\eta\big)\Big)\\
    &=2L\Big(\frac\eta2\big(n+\tfrac C\eta\big)-K\Big)^\alpha
    =2L\Big(\frac\eta2(n-K)\Big)^\alpha=L(n-K)^\alpha=\Delta^*(n).
  \end{align*}
  Therefore, $\Delta(n)\le\Delta^*(n)\sim(n-K)^\alpha$ for all $n\in\mathbb{N}$.

There exist constants $C_1,C_2>0$ such that, for any $\ell\in\mathbb{N}$,
  \begin{enumerate}
  \item for all words $w$ of length $\ell$, we have $\delta(w)\le C_1\ell^\alpha$;
  \item there exists a word $w$ of length $\ell$ with $\delta(w)\ge C_2\ell^\alpha$.
  \end{enumerate}

Because $a^2$ is
central in $H$, we have exact sequences
\begin{gather*}
  1\longrightarrow \langle a^2\rangle\longrightarrow H\longrightarrow H/\langle a^2\rangle\longrightarrow 1,\\
  1\longrightarrow C^H\longrightarrow H/\langle a^2\rangle\longrightarrow{G_{012}}\longrightarrow 1.
\end{gather*}

conclusions:
\begin{gather*}
  1\longrightarrow \langle a^2\rangle\longrightarrow H\longrightarrow H/\langle a^2\rangle\longrightarrow 1,\\
  1\longrightarrow C^H\longrightarrow H/\langle a^2\rangle\longrightarrow{G_{012}}\longrightarrow 1.
\end{gather*}

\label{lem:genP}
  The stabilizer $P=({G_{012}})_\rho$ is generated by
  \[U=\bigcup_{n\in\mathbb{N}}\sigma^n\{b,c,d,d^a,(ac)^4,\sigma([a,b])^a,\sigma^2([a,b])^a\}.\]
